#include <vector>
#include <cmath>
double sharpe(const std::vector<double>& r, double P){
    int n = r.size();
    if (n < 2) return 0.0;
    double mean = 0; for (double x : r) mean += x; mean /= n;
    double var = 0; for (double x : r) var += (x - mean) * (x - mean);
    var /= (n - 1);                 // sample variance
    double sd = std::sqrt(var);
    if (sd == 0) return 0.0;
    return (mean / sd) * std::sqrt(P);
}

import statistics, math

def sharpe(returns, P):
    n = len(returns)
    if n < 2:
        return 0.0
    mean = sum(returns) / n
    sd = statistics.stdev(returns)   # sample std
    if sd == 0:
        return 0.0
    return (mean / sd) * math.sqrt(P)
